import AppKit
import UniformTypeIdentifiers
import UserNotifications

/// One line in the recent activity list.
struct ActivityEntry: Identifiable {
    let id = UUID()
    let date = Date()
    let message: String
}

/// Shared app state: owns the rules, persists them, watches the pasteboard and applies rules.
@MainActor
final class AppModel: ObservableObject {
    static let maxBytes = 2 * 1024 * 1024
    static let skippedTypes = ["org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
                               "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword"]

    @Published var rules: [Rule] = [] { didSet { if loaded { save() } } }
    @Published var isPaused = UserDefaults.standard.bool(forKey: "pauseAll") {
        didSet { UserDefaults.standard.set(isPaused, forKey: "pauseAll") }
    }
    @Published private(set) var activity: [ActivityEntry] = []
    @Published private(set) var todayCount = 0
    @Published var errorMessage: String?

    private var loaded = false
    private var lastChangeCount = NSPasteboard.general.changeCount
    private var timer: Timer?
    private let defaults = UserDefaults.standard

    private var fileURL: URL? {
        guard let base = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask).first else { return nil }
        return base.appendingPathComponent("CopyRuleFilter", isDirectory: true).appendingPathComponent("rules.json")
    }

    init() {
        load()
        refreshTodayCount()
        let t = Timer(timeInterval: 0.4, repeats: true) { [weak self] _ in
            MainActor.assumeIsolated { self?.poll() }
        }
        RunLoop.main.add(t, forMode: .common)
        timer = t
    }

    // MARK: Persistence

    private func load() {
        defer { loaded = true }
        guard let url = fileURL, FileManager.default.fileExists(atPath: url.path) else { rules = Rule.defaults; return }
        do {
            rules = try JSONDecoder().decode(RuleFile.self, from: Data(contentsOf: url)).rules
        } catch {
            let backup = url.deletingLastPathComponent().appendingPathComponent("rules.corrupt.json")
            try? FileManager.default.removeItem(at: backup)
            try? FileManager.default.copyItem(at: url, to: backup)
            rules = Rule.defaults
            errorMessage = "Your saved rules could not be read, so defaults were loaded. The old file was kept as rules.corrupt.json."
        }
    }

    private func save() {
        guard let url = fileURL else { return }
        do {
            try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
            let encoder = JSONEncoder()
            encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
            try encoder.encode(RuleFile(rules: rules)).write(to: url, options: .atomic)
        } catch {
            log("Could not save rules: \(error.localizedDescription)")
        }
    }

    func exportRules() {
        let panel = NSSavePanel()
        panel.allowedContentTypes = [.json]
        panel.nameFieldStringValue = "CopyRuleFilter Rules.json"
        NSApp.activate(ignoringOtherApps: true)
        guard panel.runModal() == .OK, let url = panel.url else { return }
        do {
            let encoder = JSONEncoder()
            encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
            try encoder.encode(RuleFile(rules: rules)).write(to: url, options: .atomic)
        } catch {
            errorMessage = "Export failed: \(error.localizedDescription)"
        }
    }

    func importRules() {
        let panel = NSOpenPanel()
        panel.allowedContentTypes = [.json]
        panel.allowsMultipleSelection = false
        NSApp.activate(ignoringOtherApps: true)
        guard panel.runModal() == .OK, let url = panel.url else { return }
        do {
            let file = try JSONDecoder().decode(RuleFile.self, from: Data(contentsOf: url))
            guard file.version <= RuleFile.currentVersion else {
                errorMessage = "This file was made by a newer version of CopyRuleFilter (format v\(file.version))."
                return
            }
            rules += file.rules.map { var r = $0; r.id = UUID(); return r }
            log("Imported \(file.rules.count) rule(s)")
        } catch {
            errorMessage = "“\(url.lastPathComponent)” is not a valid CopyRuleFilter rules file. Your existing rules were not changed."
        }
    }

    // MARK: Pasteboard

    private func poll() {
        let pb = NSPasteboard.general
        guard pb.changeCount != lastChangeCount else { return }
        lastChangeCount = pb.changeCount
        let auto = rules.filter { $0.enabled && $0.mode == .automatic }
        guard !isPaused, !auto.isEmpty else { return }
        let source = NSWorkspace.shared.frontmostApplication?.bundleIdentifier
        if let source, ignoredApps.contains(source.lowercased()) { return }
        process(auto, source: source, notify: defaults.bool(forKey: "showNotifications"))
    }

    var ignoredApps: Set<String> {
        let raw = defaults.string(forKey: "ignoredApps") ?? ""
        return Set(raw.split(whereSeparator: { $0 == "\n" || $0 == "," })
            .map { $0.trimmingCharacters(in: .whitespaces).lowercased() }.filter { !$0.isEmpty })
    }

    /// Transforms the current clipboard in place with one on-demand rule.
    func runOnDemand(_ rule: Rule) {
        if let error = RuleEngine.validationError(for: rule) {
            notify("\(rule.name) skipped", error, force: true); return
        }
        if !process([rule], source: nil, notify: true) {
            notify(rule.name, "Clipboard unchanged", force: true)
        }
    }

    /// Reads the pasteboard, applies rules, writes back when the result differs. Returns true when written.
    @discardableResult
    private func process(_ rules: [Rule], source: String?, notify shouldNotify: Bool) -> Bool {
        let pb = NSPasteboard.general
        let types = pb.types ?? []
        guard !types.contains(where: { Self.skippedTypes.contains($0.rawValue) }) else { return false }
        let hasURLType = types.contains(.URL)
        guard !types.contains(.fileURL) else { return false }
        guard let text = pb.string(forType: .string) ?? pb.string(forType: .URL) else { return false }
        guard text.utf8.count <= Self.maxBytes else { log("Skipped clipboard larger than 2 MB"); return false }

        let rich = readRich(pb, types: types)
        let result = RuleEngine.run(rules, on: ClipContent(text: text, hasURLType: hasURLType, sourceBundleID: source))
        let changed = result.text != text || (result.forcePlain && rich != nil)
        guard changed else { return false }
        let names = result.appliedRules.joined(separator: ", ")
        if result.text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            log("\(names): produced empty output — clipboard left unchanged")
            return false
        }

        pb.clearContents()
        if let rich, !result.forcePlain {
            pb.writeObjects([restyle(rich, as: result.text)])
        } else {
            pb.setString(result.text, forType: .string)
        }
        if hasURLType, URL(string: result.text) != nil { pb.setString(result.text, forType: .URL) }
        lastChangeCount = pb.changeCount

        bumpTodayCount()
        log("\(names): transformed \(text.count) → \(result.text.count) characters")
        if shouldNotify { notify(names, String(result.text.prefix(120)), force: false) }
        return true
    }

    private func readRich(_ pb: NSPasteboard, types: [NSPasteboard.PasteboardType]) -> NSAttributedString? {
        guard types.contains(.rtf) || types.contains(.rtfd) || types.contains(.html) else { return nil }
        return pb.readObjects(forClasses: [NSAttributedString.self])?.first as? NSAttributedString
    }

    /// Re-applies the original formatting to new text: run-by-run when lengths match, else the first run's style.
    private func restyle(_ original: NSAttributedString, as text: String) -> NSAttributedString {
        let out = NSMutableAttributedString(string: text)
        let full = NSRange(location: 0, length: out.length)
        if original.length == out.length {
            original.enumerateAttributes(in: full) { attrs, range, _ in out.setAttributes(attrs, range: range) }
        } else if original.length > 0 {
            out.setAttributes(original.attributes(at: 0, effectiveRange: nil), range: full)
        }
        return out
    }

    // MARK: Activity, counter & notifications

    func log(_ message: String) {
        activity.insert(ActivityEntry(message: message), at: 0)
        if activity.count > 25 { activity.removeLast(activity.count - 25) }
    }

    private var todayKey: String {
        let f = DateFormatter(); f.dateFormat = "yyyy-MM-dd"
        return f.string(from: Date())
    }

    func refreshTodayCount() {
        todayCount = defaults.string(forKey: "countDay") == todayKey ? defaults.integer(forKey: "countValue") : 0
    }

    private func bumpTodayCount() {
        refreshTodayCount()
        todayCount += 1
        defaults.set(todayKey, forKey: "countDay")
        defaults.set(todayCount, forKey: "countValue")
    }

    static func requestNotificationAuthorization(completion: @escaping (Bool) -> Void) {
        UNUserNotificationCenter.current().requestAuthorization(options: [.alert, .sound]) { granted, _ in
            DispatchQueue.main.async { completion(granted) }
        }
    }

    private func notify(_ title: String, _ body: String, force: Bool) {
        guard force || defaults.bool(forKey: "showNotifications") else { return }
        let center = UNUserNotificationCenter.current()
        center.getNotificationSettings { settings in
            let send = {
                let content = UNMutableNotificationContent()
                content.title = title
                content.body = body
                center.add(UNNotificationRequest(identifier: UUID().uuidString, content: content, trigger: nil))
            }
            if settings.authorizationStatus == .notDetermined {
                center.requestAuthorization(options: [.alert, .sound]) { granted, _ in if granted { send() } }
            } else if settings.authorizationStatus == .authorized || settings.authorizationStatus == .provisional {
                send()
            }
        }
    }
}
